package glitch

import data.glitch_lib

# Define patterns for unnecessary privileges
root_user_patterns := {"0", "root", "Administrator", "admin"}
privileged_patterns := {"privileged", "privileged_mode"}
capability_patterns := {"ALL", "SYS_ADMIN", "NET_ADMIN", "DAC_OVERRIDE"}
admin_permission_patterns := {"AdministratorAccess", "AdministratorRole", "Owner", "root", "superuser"}
wildcard_patterns := {".*", "\\*", "ALL"}

# Check if a string value matches any of the given patterns
matches_pattern(value, patterns) {
    value.ir_type == "String"
    regex.match(patterns[_], value.value)
} else {
    value.ir_type == "VariableReference"
    # Skip variable references for now
    false
}

# Check for root/admin runtime contexts
check_elevated_runtime(attrs) {
    attr := attrs[_]
    attr.name in {"run_as_user", "user", "privileged", "privileged_mode"}
    attr.value.ir_type == "Boolean"
    attr.value.value == true
} else {
    attr := attrs[_]
    attr.name in {"run_as_user", "user"}
    matches_pattern(attr.value, root_user_patterns)
}

# Check for over-permissive IAM
check_over_permissive_iam(attrs) {
    attr := attrs[_]
    attr.name in {"role", "privilege_level", "permissions", "permission_boundary"}
    matches_pattern(attr.value, admin_permission_patterns)
} else {
    attr := attrs[_]
    attr.name in {"permissions", "policy"}
    attr.value.ir_type == "String"
    regex.match(wildcard_patterns[_], attr.value.value)
}

# Check for excessive file system permissions
check_excessive_fs(attrs) {
    attr := attrs[_]
    attr.name in {"public_access", "acl"}
    matches_pattern(attr.value, {"true", "public-read", "public-write"})
} else {
    attr := attrs[_]
    attr.name in {"security_group", "firewall_rules"}
    attr.value.ir_type == "String"
    regex.match("0\\.0\\.0\\.0/0", attr.value.value)
}

# Check for insecure container capabilities
check_insecure_capabilities(attrs) {
    attr := attrs[_]
    attr.name in {"capabilities", "added_capabilities"}
    matches_pattern(attr.value, capability_patterns)
} else {
    attr := attrs[_]
    attr.name in {"privileged", "privileged_mode"}
    attr.value.ir_type == "Boolean"
    attr.value.value == true
}

# Main rule for CWE-250 detection
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)

    # Check for any of the unnecessary privilege patterns
    check_elevated_runtime(attrs) or
    check_over_permissive_iam(attrs) or
    check_excessive_fs(attrs) or
    check_insecure_capabilities(attrs)

    result := {
        "type": "sec_def_admin",
        "element": node,
        "path": parent.path,
        "description": "Execution with Unnecessary Privileges - Configurations granting more privileges than necessary (CWE-250)"
    }
}

